(()=>{'use strict';if(window.omnibloomHost){document.getElementById('site-title').textContent='Media controls';document.getElementById('site-video').hidden=true;return;}const media=document.getElementById('site-video'),tracks=[{title:'Original moving pattern',artist:'Omnibloom studio',src:'../video/media/original-test-pattern.mp4'},{title:'A higher note',artist:'Original 440 Hz tone',src:'../video/media/tone-high.wav'},{title:'A lower note',artist:'Original 220 Hz tone',src:'../video/media/tone-low.wav'}];let index=0;const bridge=OBMediaSession.install(navigator.mediaSession,{resolveMedia:()=>media,documentKey:'fixture-document-1'});window.obFixtureBridge=bridge;window.obFixtureCalls=[];function metadata(){if(navigator.mediaSession&&typeof MediaMetadata==='function')navigator.mediaSession.metadata=new MediaMetadata({title:tracks[index].title,artist:tracks[index].artist});document.getElementById('site-title').textContent=tracks[index].title}async function select(delta,play){index=(index+delta+tracks.length)%tracks.length;media.src=tracks[index].src;media.load();metadata();if(play)await media.play()}if(navigator.mediaSession){navigator.mediaSession.setActionHandler('play',async()=>{obFixtureCalls.push('play');await media.play()});navigator.mediaSession.setActionHandler('pause',()=>{obFixtureCalls.push('pause');media.pause()});navigator.mediaSession.setActionHandler('nexttrack',async()=>{obFixtureCalls.push('nexttrack');await select(1,true)});navigator.mediaSession.setActionHandler('previoustrack',async()=>{obFixtureCalls.push('previoustrack');await select(-1,true)})}media.addEventListener('play',()=>{if(navigator.mediaSession)navigator.mediaSession.playbackState='playing'});media.addEventListener('pause',()=>{if(navigator.mediaSession)navigator.mediaSession.playbackState='paused'});media.volume=.25;select(0,false);window.obFixture={media,getIndex:()=>index};})();